import type { Content } from '@galaxy/sim';
import { ART } from './art-catalog';

// The content's drawings (the content editor, 2026-11-16, P5). The arena's art lives in the web; this catalog of it
// (art-catalog.ts, generated by a web test) lets the server, the CLI and the panel refuse a sprite or icon id the arena
// does not have, which would crash a run. The editor's galleries read it too.

export { ART } from './art-catalog';

/** Where a drawing belongs: what a content field may pick from first. */
export type ArtGroup = 'fauna' | 'nucleos' | 'sondas' | 'iconos' | 'otros';
export interface ArtInfo {
  group: ArtGroup;
  w: number;
  h: number;
  frames: number;
}

/** The content's drawing fields: where each takes its drawing from. */
export const ART_FIELDS = {
  'weapons[].icon': 'iconos',
  'passives[].icon': 'iconos',
  'probes[].sprite': 'sondas',
  'enemies[].sprite': 'fauna',
  'bosses[].sprite': 'nucleos',
} as const satisfies Record<string, ArtGroup>;

/** Every drawing the content names that the arena does not have («content_art:<id>»). */
export function contentArtIssues(c: Content): { path: string; message: string }[] {
  const out: { path: string; message: string }[] = [];
  const check = (id: string, path: string) => {
    if (!ART[id]) out.push({ path, message: `content_art:${id}` });
  };
  c.weapons.forEach((w, i) => check(w.icon, `weapons.${i}.icon`));
  c.passives.forEach((p, i) => check(p.icon, `passives.${i}.icon`));
  c.probes.forEach((p, i) => check(p.sprite, `probes.${i}.sprite`));
  c.enemies.forEach((e, i) => check(e.sprite, `enemies.${i}.sprite`));
  c.bosses.forEach((b, i) => check(b.sprite, `bosses.${i}.sprite`));
  return out;
}
